function Get-EnvValue {
    param([string]$Name)

    $line = Get-Content (Join-Path $Root ".env") |
        Where-Object {
            $_ -match "^\s*$([regex]::Escape($Name))\s*="
        } |
        Select-Object -First 1

    if (-not $line) {
        throw "Variable $Name absente de .env"
    }

    return ($line -replace "^\s*$([regex]::Escape($Name))\s*=", "").Trim()
}

